-- Complément catalogue PAC air/eau à partir du classeur transmis le 20/10/2026.
-- Fourniture et pose sont stockées séparément. Les paramètres d'aides proviennent du classeur
-- et restent indicatifs : ils doivent être confirmés selon le dossier et la réglementation applicable.
DO $$
DECLARE
  v_entreprise uuid;
  p jsonb;
  v_id uuid;
BEGIN
  SELECT id INTO v_entreprise FROM public.entreprises ORDER BY created_at LIMIT 1;
  IF v_entreprise IS NULL THEN
    RAISE NOTICE 'Aucune entreprise trouvée : aucun produit PAC air/eau mis à jour.';
    RETURN;
  END IF;

  -- Rattacher la fiche CEE BAR-TH-171 à la catégorie PAC air/eau sans marquer chaque composant
  -- comme éligible individuellement : seuls les packs complets listés ci-dessous portent les aides.
  UPDATE public.catalogue_produits
  SET fiche_cee = 'BAR-TH-171',
      caracteristiques = COALESCE(caracteristiques, '{}'::jsonb) ||
        '{"fiche_cee":"BAR-TH-171 (vA82-5 depuis le 01/09/2026)","source_fiche_cee":"Classeur Reno Soluces du 20/10/2026","aides_estimatives_a_verifier":true}'::jsonb
  WHERE entreprise_id = v_entreprise AND categorie = 'pac_air_eau';

  FOR p IN SELECT value FROM jsonb_array_elements($products$
