$products$::jsonb) LOOP
    SELECT id INTO v_id FROM public.catalogue_produits
    WHERE entreprise_id = v_entreprise AND categorie = 'pac_air_eau' AND reference = p->>'reference'
    LIMIT 1;

    IF v_id IS NULL THEN
      INSERT INTO public.catalogue_produits (
        entreprise_id, categorie, nom, marque, reference, description, caracteristiques,
        prix_unitaire_ht, forfait_pose_ht, unite, tva_taux, eligible_mpr, eligible_cee,
        fiche_cee, actif, public_cible
      ) VALUES (
        v_entreprise, p->>'categorie', p->>'nom', p->>'marque', p->>'reference',
        p->>'description', p->'caracteristiques',
        (p->>'prix_ht')::numeric, (p->>'pose_ht')::numeric, p->>'unite',
        (p->>'tva')::numeric, (p->>'eligible_mpr')::boolean, (p->>'eligible_cee')::boolean,
        p->>'fiche_cee', true, 'particulier'
      );
    ELSE
      UPDATE public.catalogue_produits SET
        nom = p->>'nom',
        marque = p->>'marque',
        description = p->>'description',
        caracteristiques = COALESCE(caracteristiques, '{}'::jsonb) || (p->'caracteristiques'),
        prix_unitaire_ht = (p->>'prix_ht')::numeric,
        forfait_pose_ht = (p->>'pose_ht')::numeric,
        unite = p->>'unite',
        tva_taux = (p->>'tva')::numeric,
        eligible_mpr = (p->>'eligible_mpr')::boolean,
        eligible_cee = (p->>'eligible_cee')::boolean,
        fiche_cee = p->>'fiche_cee',
        actif = true
      WHERE id = v_id;
    END IF;
    v_id := NULL;
  END LOOP;
END $$;
